+void ShaderTextEditor::_bind_methods() {
+	ClassDB::bind_method("_show_warnings_panel", &ShaderTextEditor::_show_warnings_panel);
+	ClassDB::bind_method("_warning_clicked", &ShaderTextEditor::_warning_clicked);
