+	int warning_count = 0;
+
+	warnings_panel->push_table(2);
+	for (const ShaderWarning &w : warnings) {
+		if (warning_count == 0) {
+			if (saved_treat_warning_as_errors) {
+				const String message = (w.get_message() + " " + TTR("Warnings should be fixed to prevent errors.")).replace("[", "[lb]");
